import React, { useCallback } from "react";
import { Link } from "react-router-dom";
import DotGrid from "../components/DotGrid";
import { useTranslation } from "../contexts/LanguageContext";
import homeDemo from "../assets/Home.png";
import onboardingDemo from "../assets/OnBoarding.png";


function Home() {
  const { t } = useTranslation();
  const handleDemoClick = useCallback(() => {
    if (typeof window === "undefined") return;
    try {
      sessionStorage.setItem("sayfeDemoAccess", "true");
    } catch (error) {
      console.warn("Unable to persist demo access flag:", error);
    }
  }, []);

  return (
    <div className="App">
      <main className="page-main home-main">
        
        <DotGrid
          className="dotGrid-background"
          dotSize={12}
          gap={18}
          baseColor="#73ac84"
          activeColor="#73ac84"
          baseOpacity={0.12}
          activeOpacity={0.26}
          proximity={140}
          shockRadius={260}
          shockStrength={4.2}
          resistance={820}
          returnDuration={1.45}
          style={{ width: "100%", height: "100%" }}
        />
        
        {/* === Demo Section === */}
        <section className="demo-section">
          <div className="section-shell demo-shell">
            <div className="demo-content">
              <h2
                className="demo-title"
                dangerouslySetInnerHTML={{ __html: t("home.demoTitle") }}
              ></h2>
              <p
                className="demo-text"
                dangerouslySetInnerHTML={{ __html: t("home.demoText") }}
              ></p>
              <Link to="/demo" className="demo-btn" onClick={handleDemoClick}>
                {t("home.demoCta")}
              </Link>
            </div>

            <div className="demo-visual">
              <div className="phone-stack">
                <div
                  className="phone-frame phone-left"
                  role="img"
                  aria-label="Sayfe App home screen preview"
                  data-screen={homeDemo}
                  style={{ "--phone-screen": `url(${homeDemo})` }}
                />
                <div
                  className="phone-frame phone-right"
                  role="img"
                  aria-label="Sayfe onboarding flow preview"
                  data-screen={onboardingDemo}
                  style={{ "--phone-screen": `url(${onboardingDemo})` }}
                />
              </div>
            </div>
          </div>
        </section>

        {/* === Hero Section === */}
        <section className="hero">
          <div className="section-shell">
            <h2
              className="hero-title"
              dangerouslySetInnerHTML={{ __html: t("home.heroTitle") }}
            ></h2>
            <p
              className="hero-text"
              dangerouslySetInnerHTML={{ __html: t("home.heroText") }}
            ></p>
            <Link to="/waitlist" className="cta-btn">
              {t("home.heroCta")}
            </Link>
          </div>
        </section>

        {/* === Features Section === */}
        <section className="features">
          <div className="section-shell">
            <h3
              dangerouslySetInnerHTML={{ __html: t("home.featuresTitle") }}
            ></h3>
            <div className="feature-grid">
              <div className="feature-card">
                <h4>{t("home.features.realtime.title")}</h4>
                <p>{t("home.features.realtime.text")}</p>
              </div>
              <div className="feature-card">
                <h4>{t("home.features.ai.title")}</h4>
                <p>{t("home.features.ai.text")}</p>
              </div>
              <div className="feature-card">
                <h4>{t("home.features.privacy.title")}</h4>
                <p>{t("home.features.privacy.text")}</p>
              </div>
            </div>
          </div>
        </section>
      </main>
    </div>
  );
}

export default Home;
